const chapterLoaders: Record<
  ReadingChapterId,
  () => Promise<{ default: string }>
> = {
  "jane-eyre": () => import("./chapters/jane-eyre.txt?raw"),
  dracula: () => import("./chapters/dracula.txt?raw"),
  "oliver-twist": () => import("./chapters/oliver-twist.txt?raw"),
  "three-musketeers": () => import("./chapters/three-musketeers.txt?raw"),
};

export function readingChapterById(id: string | undefined) {
  return READING_CHAPTERS.find((chapter) => chapter.id === id);
}

export async function loadReadingChapter(id: ReadingChapterId) {
  const text = (await chapterLoaders[id]()).default;
  return text
    .split(/\n\s*\n/)
    .map((paragraph) => paragraph.replace(/\s+/g, " ").trim())
    .filter(Boolean);
}
